// GEP 資產構建器
const AssetBuilder = {
  build: async function(genes, capsules) {
    const bundles = [];
    for (const gene of genes) {
      const capsule = capsules.find(c => c.trigger.some(t => gene.signals_match.includes(t)));
      const event = this.createEvent(gene, capsule);
      bundles.push({ gene, capsule, event });
    }
    return bundles;
  },
  createEvent: function(gene, capsule) {
    return {
      type: 'EvolutionEvent',
      intent: 'optimize',
      genes_used: [gene.id],
      outcome: { score: 0.95, status: 'success' }
    };
  }
};
module.exports = AssetBuilder;
